const info:Record<Game,{name:string;tag:string;desc:string;level:string;time:string;icon:string;rules:string}>={
  klondike:{name:'Косынка',tag:'НЕСТАРЕЮЩАЯ КЛАССИКА',desc:'Знакомая с первого хода',level:'Легко освоить',time:'5–10 мин',icon:'♠',rules:'Соберите четыре дома по мастям от туза до короля. В столбцах чередуйте красные и чёрные карты по убыванию. Переносить можно целые правильные последовательности. В пустой столбец кладётся только король. Нажимайте на колоду, чтобы открывать по одной или по три карты. Колоду можно перелистывать снова.'},
  spider:{name:'Паук',tag:'ИСКУССТВО СТРАТЕГИИ',desc:'Каждая масть — новый вызов',level:'Есть над чем подумать',time:'15–25 мин',icon:'♣',rules:'Соберите восемь последовательностей одной масти от короля до туза. Полная последовательность убирается автоматически. На карту кладётся карта на единицу младше любой масти, но переносить вместе можно только последовательность одной масти. В пустое место кладётся любая карта или правильная серия. Новая раздача добавляет по карте в каждый столбец; для неё все столбцы должны быть заняты.'},
  freecell:{name:'Свободная ячейка',tag:'ВСЁ В ВАШИХ РУКАХ',desc:'Никакой случайности после раздачи',level:'Для любителей логики',time:'10–20 мин',icon:'♦',rules:'Соберите дома по мастям от туза до короля. Все карты открыты. В столбцах чередуйте цвета по убыванию. Четыре свободные ячейки вмещают по одной карте. Длина переносимой серии ограничена числом свободных ячеек и пустых столбцов: (ячейки + 1) × 2 в степени числа пустых столбцов, кроме места назначения. В пустой столбец можно положить любую карту.'},
  pyramid:{name:'Пирамида',tag:'МАГИЯ ЧИСЛА ТРИНАДЦАТЬ',desc:'Найдите идеальную пару',level:'Быстрая головоломка',time:'3–7 мин',icon:'♥',rules:'Уберите все 28 карт пирамиды. Выбирайте две свободные карты с суммой 13: туз — 1, валет — 11, дама — 12. Король убирается одним нажатием. Свободна карта, не перекрытая двумя нижними картами. Верхнюю карту сброса можно соединять с картой пирамиды. Открывайте резерв по одной карте. Доступны два повторных прохода резерва.'},
  yukon:{name:'Юкон',tag:'СВОБОДА НЕОЖИДАННЫХ ХОДОВ',desc:'Переносите группы без порядка',level:'Для вдумчивой игры',time:'10–20 мин',icon:'♦',rules:'Соберите дома по мастям от туза до короля. В столбцах кладите карты по убыванию с чередованием цвета. Можно переносить любую открытую карту вместе со всеми лежащими на ней картами — порядок внутри группы не важен. В пустой столбец кладётся король с любой открытой группой. Вся колода уже на столе: резерва нет.'},
  golf:{name:'Гольф',tag:'КОРОТКАЯ ПАРТИЯ · БОЛЬШАЯ ЦЕПОЧКА',desc:'Семь столбцов, один точный ход',level:'Быстрая головоломка',time:'3–5 мин',icon:'♣',rules:'Уберите все 35 карт со стола в сброс. Доступны только верхние карты семи столбцов. Карта должна быть на единицу старше или младше карты сброса; масть не важна. Переход король–туз запрещён: на туза можно положить только двойку, на короля — только даму. Если ходов нет, откройте одну карту из резерва. Повторного прохода резерва нет.'},
  tripeaks:{name:'Три вершины',tag:'ОДИН ШАГ ДО ГАРМОНИИ',desc:'Покорите три карточные вершины',level:'Легко освоить',time:'3–7 мин',icon:'♠',rules:'Уберите все карты трёх вершин. Нажимайте на свободную карту на единицу старше или младше верхней карты сброса. Масть не важна; туз соседствует с двойкой и королём. Карта свободна, когда обе карты под ней убраны. Если подходящих карт нет, открывайте резерв. Повторного прохода резерва нет.'}
};
const paths:Record<string,string>={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 19 19M5 19l1.5-1.5M17.5 6.5 19 5',chart:'M4 20V10M12 20V4M20 20v-7',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16M14 6l6 6-6 6',back:'M20 12H4M10 6l-6 6 6 6',undo:'M9 5 4 10l5 5M4 10h9a6 6 0 0 1 0 12',hint:'M9 18h6M9 21h6M8 14a6 6 0 1 1 8 0l-1 2H9Z',restart:'M20 8A9 9 0 1 0 21 15M20 3v5h-5',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3M12 18h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'M6 6l12 12M6 18 18 6',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',trophy:'M8 3h8v6a4 4 0 0 1-8 0ZM8 5H4v3a4 4 0 0 0 4 4M16 5h4v3a4 4 0 0 1-4 4M12 13v6M7 21h10',check:'m5 12 4 4L20 5',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',volume:'m3 9 5 0 5-5v16l-5-5H3ZM17 8a7 7 0 0 1 0 8',pause:'M8 5v14M16 5v14',play:'m7 4 14 8-14 8Z'};
const icon=(name:string)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]??paths.grid}"/></svg>`;
let data=load();journey(data);let page='home';let collectionFilter='all';let lastXP=0;let towerGame:Game=data.last;let pendingBot='nina';let active:Game=data.last;let selected:Place|null=null;let pair:number|null=null;let highlighted:number[]=[];let modal:string|null=null;let paused=false;let toastTimer:ReturnType<typeof setTimeout>;let audio:AudioContext|null=null;
const app=document.querySelector<HTMLDivElement>('#app')!;
const club=()=>data.club??=freshClub();
const towerRun=():TowerRun|undefined=>club().towers[towerGame];
const session=():Session|undefined=>page==='marathon-game'?journey(data).marathon?.session??undefined:page==='race'?club().race?.player:page==='tower-game'?towerRun()?.session??undefined:data.sessions[active];
const time=(n:number)=>`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`;
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
function persist(){if(!save(data))toast('Не удалось сохранить прогресс: проверьте свободное место. Экспортируйте резервную копию в настройках.');}
function toast(message:string){const el=document.querySelector('#toast')!;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function sound(){if(!data.settings.sound)return;try{audio??=new AudioContext();void audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(620,audio.currentTime);o.frequency.exponentialRampToValueAtTime(330,audio.currentTime+.07);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.09);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.1);}catch{}}
function dateLabel(){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',timeZone:'Europe/Moscow'}).format(new Date());}
function start(game:Game,daily=false,force=false,seedOverride?:number){
  active=game;data.last=game;
  const date=moscowDate();const old=data.sessions[game];
  if(force||!old||(daily&&old.daily!==date)||(!daily&&old.daily)){
    const seed=daily?dailySeed(date,game):seedOverride??crypto.getRandomValues(new Uint32Array(1))[0];
    const initial=createGame(game,seed,{drawCount:daily?1:Number((document.querySelector('#draw-count') as HTMLSelectElement)?.value??old?.state.drawCount??1),suits:daily?1:Number((document.querySelector('#suits') as HTMLSelectElement)?.value??old?.state.suits??1)});
    data.sessions[game]={state:initial,initial:clone(initial),history:[],seconds:0,daily:daily?date:null,counted:false};
    data.stats[game].played++;
  }
  selected=null;pair=null;highlighted=[];paused=false;modal=null;page='game';persist();render();
}
function move(action:Action){
  const se=session();if(!se||paused||modal||(page==='race'&&club().race?.status!=='playing')||(page==='tower-game'&&towerRun()?.failed))return false;
  const next=apply(se.state,action);if(!next)return false;
  se.history.push(clone(se.state));if(se.history.length>150)se.history.shift();se.state=next;selected=null;pair=null;highlighted=[];sound();recordMove(data,moscowDate());
  lastXP=0;if(next.won){const m=journey(data).marathon;const key=page==='race'?`duel:${club().race!.id}`:page==='tower-game'?`tower:${towerRun()!.joined}:${towerRun()!.floor}`:page==='marathon-game'?`marathon:${m!.id}:${m!.stage}`:`solo:${active}:${next.seed}`;lastXP=recordWin(data,{key,game:active,kind:page==='race'?'duel':page==='tower-game'?'tower':page==='marathon-game'?'marathon':se.daily?'daily':'solo',seconds:se.seconds,hints:se.hintsUsed??0,undos:se.undosUsed??0},moscowDate());}
  if(next.won){if(page==='marathon-game'){finishMarathonStage(data);modal='marathon-win';}else if(page==='race'){finishRace(club(),'win');modal='race-result';}else if(page==='tower-game'){clearFloor(club(),towerRun()!);modal='tower-win';}else modal='win';}
  if(next.won&&!se.counted&&page==='game'){se.counted=true;award(club(),`solo:${active}:${next.seed}`,se.daily?100:60);const r=data.stats[active];r.won++;r.seconds+=se.seconds;r.best=r.best===null?se.seconds:Math.min(r.best,se.seconds);if(se.daily){const key=`${se.daily}:${active}`;if(!data.daily.includes(key))data.daily.push(key);}modal='win';}
  persist();render();return true;
}
function undo(){const se=session();if(!se||paused||!se.history.length||se.state.won||(page==='race'&&club().race?.status!=='playing'))return;if(page==='tower-game'){const t=towerRun()!;if(t.failed||t.undoUsed>=towerRules(t.game,t.floor).undos){toast('Лимит отмен на этом этаже исчерпан.');return;}t.undoUsed++;}se.undosUsed=(se.undosUsed??0)+1;se.state=se.history.pop()!;selected=null;pair=null;highlighted=[];persist();render();}
function miniCard(rank:string,suit:string,cls=''){return `<div class="mini-card ${cls} ${['♥','♦'].includes(suit)?'red':''}"><b>${rank}<small>${suit}</small></b><span class="suit-art suit-${symbols.indexOf(suit)}"></span></div>`;}
function art(g:Game){
  if(g==='pyramid')return `<div class="mini-pyramid">${miniCard('К','♦','p1')}${miniCard('6','♠','p2')}${miniCard('7','♥','p3')}${miniCard('Т','♣','p4')}${miniCard('Д','♦','p5')}${miniCard('9','♠','p6')}</div>`;
  if(g==='tripeaks')return `<div class="mini-peaks">${miniCard('5','♠')}${miniCard('6','♥')}${miniCard('7','♣')}</div>`;
  return `<div class="mini-fan">${miniCard(g==='spider'?'К':'Т','♠')}${miniCard(g==='spider'?'Д':'2',g==='spider'?'♠':'♥')}${miniCard(g==='spider'?'В':'3','♠')}</div>`;
}
function sidebar(){return `<aside class="sidebar"><button class="brand" data-nav="home" aria-label="На главную"><span class="brand-mark">♠</span><span>ПАСЬЯНС<small>К О Л Л Е К Ц И Я</small></span></button><div class="side-caption">ВАШ ТИХИЙ ЧАС</div><nav>${[['home','grid','Коллекция'],['modes','play','Режимы игры'],['journey','trophy','Мой путь'],['duel','play','Дуэль с ботом'],['tower','trophy','Царь горы'],['league','chart','Лига ботов'],['shop','grid','Магазин'],['daily','sun','Задание дня'],['stats','chart','Статистика'],['settings','settings','Настройки']].map(([id,i,label])=>`<button data-nav="${id}" class="nav-item ${(page===id||(page==='race'&&id==='duel')||(page==='tower-game'&&id==='tower')||(page==='marathon-game'&&id==='modes'))?'active':''}">${icon(i)}${label}${id==='daily'||(id==='journey'&&pendingRewards(data,moscowDate()))?'<i class="nav-dot"></i>':''}</button>`).join('')}</nav><div class="side-games"><div class="side-caption">ЛЮБИМЫЕ ИГРЫ</div>${games.map(g=>`<button data-game="${g}" class="game-link ${page==='game'&&active===g?'active':''}"><span class="${g==='pyramid'||g==='freecell'?'warm':''}">${info[g].icon}</span>${info[g].name}</button>`).join('')}</div><div class="sidebar-bottom"><button class="sidebar-level" data-nav="journey"><b>${level(journey(data).xp).level}</b><span>${level(journey(data).xp).title}<small>${journey(data).xp} XP · Мой путь →</small></span></button><span class="small-ornament">✧</span><p>Немного тишины.<br>Немного магии карт.</p><small>БЕЗ РЕКЛАМЫ · БЕЗ СУЕТЫ</small></div></aside>`;}
function header(title:string,subtitle:string){return `<header class="page-header"><div><div class="eyebrow">ПАСЬЯНС · КОЛЛЕКЦИЯ</div><h1>${title}</h1><p>${subtitle}</p></div><div class="header-right"><button class="coin-badge" data-nav="shop" aria-label="Магазин и баланс монет">✧ ${club().coins}</button><span class="date">${icon('sun')}${dateLabel()}</span><button class="round-button" data-nav="settings" aria-label="Настройки">${icon('settings')}</button></div></header>`;}
function home(){
  const current=data.sessions[data.last];const resume=current&&!current.state.won;
  return `${header('Игра в удовольствие','Любимые пасьянсы. Новые маленькие победы.')}${journeyStrip(data)}<section class="hero"><div class="hero-lines"></div><div class="hero-copy"><div class="hero-eyebrow"><span></span> ВРЕМЯ ДЛЯ СЕБЯ</div><h2>Всё сложится.<br><em>Карта за картой.</em></h2><p>Оставьте дела за пределами стола.<br>Здесь есть только вы и следующий ход.</p><button class="gold-button" data-game="${resume?data.last:'klondike'}">${icon('play')}${resume?'Продолжить игру':'Начать с «Косынки»'}${icon('arrow')}</button><div class="hero-note">${resume?`${info[data.last].name} · ${current.state.moves} ходов · ${time(current.seconds)}`:'Без регистрации. Без рекламы. В своём ритме.'}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><span class="spark s1">✧</span><span class="spark s2">✧</span><div class="hero-card hc1">${miniCard('К','♣')}</div><div class="hero-card hc2">${miniCard('Д','♥')}</div><div class="hero-card hc3">${miniCard('Т','♠')}</div><span class="art-caption">ИСКУССТВО НЕ СПЕШИТЬ</span></div></section><div class="section-title"><h2>Найдите свою игру <span>07</span></h2><span>Семь способов отвлечься от суеты</span></div><div class="collection-filters">${[['all','Все игры'],['quick','Быстрая партия'],['strategy','Подумать']].map(([id,label])=>`<button class="${collectionFilter===id?'active':''}" data-filter="${id}">${label}</button>`).join('')}</div><section class="game-grid">${games.filter(g=>collectionFilter==='all'||(collectionFilter==='quick'?['golf','pyramid','tripeaks'].includes(g):['yukon','freecell','spider','klondike'].includes(g))).map((g,i)=>`<button class="game-tile tile-${g}" data-game="${g}"><div class="tile-art"><span class="tile-number">0${games.indexOf(g)+1}</span>${['yukon','golf'].includes(g)?'<span class="new-game-tag">НОВИНКА</span>':''}${art(g)}<span class="tile-play">${icon('play')}</span></div><div class="tile-copy"><h3>${info[g].name}</h3><p>${info[g].desc}</p><span class="game-mastery-line">${journey(data).mastery[g]?.wins??0} побед · ${journey(data).mastery[g]?.xp??0} XP</span><div class="tile-meta"><span>${icon('clock')}${info[g].time}</span>${icon('arrow')}</div></div></button>`).join('')}</section><div class="mode-promo"><button data-nav="duel"><span>⚔</span><div><b>Дуэль с характером</b><small>Два стола. Кто быстрее?</small></div><i>→</i></button><button data-nav="tower"><span>♛</span><div><b>Царь горы</b><small>Семь ступеней к вершине</small></div><i>↑</i></button></div><section class="bottom-grid"><button class="daily-banner" data-nav="daily"><span class="daily-icon">${icon('sun')}</span><div><div class="eyebrow">НОВЫЙ ДЕНЬ — НОВАЯ РАЗДАЧА</div><h3>Маленький ритуал на каждый день</h3><p>Семь общих раздач. Сколько покорится вам сегодня?</p></div><span class="banner-arrow">${icon('arrow')}</span></button><div class="quote"><span>“</span><p>Красота игры —<br>в умении не спешить.</p><small>ВАШ ХОД. ВАШ РИТМ.</small></div></section><footer class="footer"><span>Сделано для хороших пауз.</span><span>♠ <i>♥</i> ♣ <i>♦</i></span><span>Весь прогресс — на вашем устройстве</span></footer>`;
}
function daily(){const date=moscowDate();return `${header('Задание дня','Одна дата. Семь раздач. Ваш личный вызов.')}<section class="daily-intro"><span class="daily-large">${icon('sun')}</span><div><div class="eyebrow">${dateLabel()} · МОСКОВСКОЕ ВРЕМЯ</div><h2>Начните день с маленькой победы</h2><p>Раздачи одинаковы для всех и обновляются в полночь по Москве.<br>Случайная раздача может не иметь решения — это часть классического пасьянса.</p></div><span class="daily-progress">${games.filter(g=>data.daily.includes(`${date}:${g}`)).length}<small>из 7 побед</small></span></section><section class="daily-list">${games.map(g=>{const done=data.daily.includes(`${date}:${g}`);return `<article class="daily-row"><div class="daily-art tile-${g}">${art(g)}</div><div><div class="eyebrow">${info[g].tag}</div><h2>${info[g].name}</h2><p>${info[g].level} · ${info[g].time}</p></div><button class="${done?'soft-button':'primary-button'}" data-daily="${g}">${done?icon('check'):'Начать'}${done?'Пройдено':icon('arrow')}</button></article>`;}).join('')}</section>`;}
function stats(){const all=Object.values(data.stats);const played=all.reduce((n,r)=>n+r.played,0),won=all.reduce((n,r)=>n+r.won,0);return `${header('Ваши маленькие победы','Каждая партия — часть вашей истории.')}<div class="stat-grid">${[[played,'СЫГРАНО ПАРТИЙ'],[won,'ПОБЕД'],[`${played?Math.round(won/played*100):0}%`,'ДОЛЯ ПОБЕД'],[data.daily.length,'ЗАДАНИЙ ПРОЙДЕНО']].map(([n,l])=>`<div class="stat-card"><span>${n}</span><small>${l}</small></div>`).join('')}</div><section class="stats-table"><h2>История по играм</h2><table><thead><tr><th>Пасьянс</th><th>Партии</th><th>Победы</th><th>Лучшее время</th></tr></thead><tbody>${games.map(g=>`<tr><td><span class="table-suit">${info[g].icon}</span>${info[g].name}</td><td>${data.stats[g].played}</td><td>${data.stats[g].won}</td><td>${data.stats[g].best===null?'—':time(data.stats[g].best!)}</td></tr>`).join('')}</tbody></table><p class="muted">Партия учитывается при создании раздачи. Повтор той же раздачи не добавляет новую партию. Рекорды фиксируются после победы.</p></section>`;}
function settings(){return `${header('Ваш стол. Ваши правила.','Пусть каждая деталь будет по душе.')}<section class="settings-panel"><h2>Атмосфера</h2><p>Выберите цвет игрового стола</p><div class="theme-options">${[['forest','Лесной изумруд'],['midnight','Полночь'],['plum','Бархатный вечер']].map(([id,label])=>`<button class="theme-choice theme-${id} ${data.settings.theme===id?'chosen':''}" data-theme="${id}"><span>♠</span><b>${label}</b>${data.settings.theme===id?icon('check'):''}</button>`).join('')}</div><h2>Рубашка карт</h2><p>Новые рубашки доступны в <button class="inline-link" data-nav="shop">магазине за игровые монеты →</button></p><div class="back-options">${backs.filter(b=>club().owned.includes(b.id)).map(({id,name:label})=>`<button class="back-choice ${data.settings.back===id?'chosen':''}" data-back="${id}"><div class="back-preview back-${id}"><span>♠</span></div>${label}</button>`).join('')}</div>${[['sound','volume','Звуки карт','Мягкий отклик каждого хода'],['motion','sun','Плавные переходы','Немного движения, немного жизни']].map(([id,i,label,desc])=>`<button class="setting-toggle" data-toggle="${id}" role="switch" aria-checked="${data.settings[id as 'sound'|'motion']}">${icon(i)}<span><strong>${label}</strong><small>${desc}</small></span><i class="switch ${data.settings[id as 'sound'|'motion']?'on':''}"></i></button>`).join('')}<h2>Лицо карт</h2><p>Декоративные масти с портретами или контрастная классика — правила одинаковы.</p><div class="face-options"><button class="soft-button ${(data.settings.faces??'ornate')==='ornate'?'chosen':''}" data-faces="ornate">Атлас и золото</button><button class="soft-button ${data.settings.faces==='classic'?'chosen':''}" data-faces="classic">Контрастная классика</button></div><h2>Ваш прогресс</h2><p>Партии сохраняются автоматически на этом устройстве. Резервная копия поможет перенести их на другой компьютер.</p><div class="button-row"><button class="soft-button" data-action="export">${icon('download')}Экспорт прогресса</button><button class="soft-button" data-action="import">Импорт из файла</button></div><input type="file" id="import-file" accept="application/json,.json" hidden><div class="about"><span>♠</span><h3>Пасьянс · Коллекция</h3><p>Версия 1.1 · Семь классических игр на русском.<br>Без рекламы, покупок и обязательной регистрации.<br>Оригинальное оформление. Не связана с Microsoft.</p></div></section>`;}
function cardFace(card:Card){
  if(card.rank>10&&data.settings.faces==='classic')return `<span class="classic-court"><b>${ranks[card.rank]}</b><small>${symbols[card.suit]}</small></span>`;
  if(card.rank>10){const n=card.rank===13?6:card.rank===12?5:0;return `<span class="court-art" style="--gx:${n%2*100}%;--gy:${Math.floor(n/2)/3*100}%"><span>${symbols[card.suit]}</span></span>`;}
  if(card.rank===1)return `<span class="suit-art suit-${card.suit}"></span>`;
  const corners=[[38,19],[62,19],[38,81],[62,81]],sides=[[38,19],[62,19],[38,50],[62,50],[38,81],[62,81]],long=[[38,18],[62,18],[38,39],[62,39],[38,61],[62,61],[38,82],[62,82]];
  const points=card.rank===2?[[50,22],[50,78]]:card.rank===3?[[50,19],[50,50],[50,81]]:card.rank===4?corners:card.rank===5?[...corners,[50,50]]:card.rank===6?sides:card.rank===7?[...sides,[50,34]]:card.rank===8?[...sides,[50,34],[50,66]]:card.rank===9?[...long,[50,50]]:[...long,[50,28.5],[50,71.5]];
  return `<span class="card-pips">${points.map(([x,y])=>`<span class="pip suit-art suit-${card.suit} ${y>50?'inverted':''}" style="left:${x}%;top:${y}%"></span>`).join('')}</span>`;
}
function cardHtml(card:Card,p:Place,extra=''){
  const se=session()!;const blocked=p.zone==='columns'&&((['pyramid','tripeaks'].includes(se.state.game)&&!exposed(se.state,p.pile))||(se.state.game==='golf'&&p.index!==se.state.columns[p.pile].length-1));
  const chosen=selected&&selected.zone===p.zone&&selected.pile===p.pile&&p.index>=selected.index||pair===card.id;
  return `<button class="card ${card.up?'face':'face-down'} ${red(card)?'red':''} ${blocked?'blocked':''} ${chosen?'selected':''} ${highlighted.includes(card.id)?'hinted':''} ${extra}" data-card="${p.zone}:${p.pile}:${p.index}" data-id="${card.id}" ${card.up&&!blocked?'draggable="true"':''} aria-label="${card.up?`${ranks[card.rank]} ${symbols[card.suit]}${blocked?', перекрыта':''}`:'Закрытая карта'}" ${!card.up||blocked?'aria-disabled="true" disabled':''}><span class="card-corner">${ranks[card.rank]}<small>${symbols[card.suit]}</small></span><span class="card-center">${cardFace(card)}</span><span class="card-corner bottom">${ranks[card.rank]}<small>${symbols[card.suit]}</small></span></button>`;
}
function slot(zone:Place['zone'],p:number,label:string,content=''){return `<div class="slot ${zone}" data-target="${zone}:${p}" ${!content?'tabindex="0" role="button" aria-label="Свободное место для карты"':''}><span class="slot-symbol">${label}</span>${content}</div>`;}
function board(){const se=session()!,s=se.state;let top='';
  if(s.game==='freecell')top=`<div class="top-group">${s.cells.map((p,i)=>slot('cells',i,i>=4-(s.lockedCells??0)?'×':'',p[0]?cardHtml(p[0],{zone:'cells',pile:i,index:0}):'')).join('')}<span class="group-caption">СВОБОДНЫЕ ЯЧЕЙКИ</span></div>`;
  else if(s.game!=='yukon')top=`<div class="top-group stock-group"><button class="slot stock ${s.stock.length?'has-stock':''}" data-action="draw" aria-label="${s.stock.length?'Открыть колоду':'Перелистать колоду'}">${s.stock.length?`<span class="stock-back back-${data.settings.back}">♠</span><span class="stock-count">${s.game==='spider'?s.stock.length/10:s.stock.length}</span>`:icon('restart')}</button>${s.game!=='spider'?slot('waste',0,'',s.waste.at(-1)?cardHtml(s.waste.at(-1)!,{zone:'waste',pile:0,index:s.waste.length-1}):''):''}<span class="group-caption">${s.game==='spider'?'РАЗДАЧИ':s.game==='pyramid'?`РЕЗЕРВ · ${2-s.recycles} ПОВТОРА`:s.game==='klondike'?`КОЛОДА · ПО ${s.drawCount}`:'РЕЗЕРВ'}</span></div>`;
  if(s.game==='yukon')top='<div class="yukon-note">Вся колода на столе<br><small>Переносите открытые группы в любом порядке</small></div>';
  if(s.game==='klondike'||s.game==='freecell'||s.game==='yukon')top+=`<div class="top-group">${s.foundations.map((p,i)=>slot('foundations',i,symbols[i],p.at(-1)?cardHtml(p.at(-1)!,{zone:'foundations',pile:i,index:p.length-1}):'')).join('')}<span class="group-caption">ДОМА · ОТ ТУЗА ДО КОРОЛЯ</span></div>`;
  if(s.game==='spider')top+=`<div class="spider-goals">${s.foundations.map(p=>`<span class="${p.length?'complete':''}">${p.length?'♠':'♧'}</span>`).join('')}<small>СОБРАНО ${s.foundations.filter(p=>p.length).length} ИЗ 8</small></div>`;
  if(s.game==='pyramid'||s.game==='tripeaks'){
    const triangular=s.columns.map((p,i)=>{
      let row:number,x:number;
      if(s.game==='pyramid'){row=Math.floor((Math.sqrt(8*i+1)-1)/2);x=3-row/2+(i-row*(row+1)/2);}
      else if(i<3){row=0;x=1+i*3;}
      else if(i<9){row=1;x=.5+Math.floor((i-3)/2)*3+(i-3)%2;}
      else if(i<18){row=2;x=Math.floor((i-9)/3)*3+(i-9)%3;}
      else {row=3;x=i-18;}
      return `<div class="triangle-position" style="--x:${x};--y:${row};z-index:${row+1}">${p[0]?cardHtml(p[0],{zone:'columns',pile:i,index:0}):''}</div>`;
    }).join('');
    return `<div class="triangle-board ${s.game}"><div class="triangle-cards">${triangular}</div><div class="triangle-reserve">${top}<div class="triangle-tip">${s.game==='pyramid'?'Выберите пару с суммой 13':'На единицу старше или младше'}<small>${s.game==='pyramid'?'Т = 1 · В = 11 · Д = 12 · К = 13':'Туз соединяется с двойкой и королём'}</small></div></div></div>`;
  }
  return `<div class="board-top">${top}</div><div class="columns cols-${s.columns.length}">${s.columns.map((col,i)=>`<div class="column" style="min-height:calc(var(--card-h) + ${Math.max(0,col.length-1)} * var(--step))" data-target="columns:${i}" ${!col.length?'tabindex="0" role="button" aria-label="Пустой столбец"':''}><span class="empty-column"></span>${col.map((c,j)=>`<div class="stack-card" style="top:calc(${j} * var(--step))">${cardHtml(c,{zone:'columns',pile:i,index:j})}</div>`).join('')}</div>`).join('')}</div>`;
}
function gameView(){const se=session();if(!se)return home();const s=se.state;return `${page==='marathon-game'?marathonBanner(data):page==='tower-game'?towerGameHeading(towerRun()!):''}<div class="game-heading"><div><button class="breadcrumb" data-nav="home">${icon('back')}Коллекция</button><h1>${info[active].name}<small>${se.variant==='calm'?'Сад спокойствия':se.variant==='guided'?'Разрешимая раздача':se.variant==='numbered'?'Раздача № '+s.seed:se.daily?'Задание дня · '+esc(se.daily):active==='spider'?`${s.suits} ${s.suits===1?'масть':s.suits===2?'масти':'масти'}`:info[active].tag.toLowerCase()}</small></h1></div><div class="game-counters"><div><span id="timer">${time(se.seconds)}</span><small>ВРЕМЯ</small></div><div><span>${s.moves}</span><small>ХОДЫ</small></div><div><span>${s.score}</span><small>ОЧКИ</small></div><button class="round-button" data-action="pause" aria-label="Приостановить игру">${icon('pause')}</button></div></div>${!journey(data).tutorialDone&&page==='game'?`<div class="first-game-guide"><div><b>Каждому ходу — своё время</b><span>Выберите карту, затем место. Можно перетаскивать. H — подсказка, Ctrl+Z — отмена; правила рядом со столом.</span></div><button data-action="tutorial-close">Понятно ✓</button></div>`:''}<section class="game-table theme-${data.settings.theme} back-style-${data.settings.back}"><div class="table-grain"></div><div class="table-watermark">♠</div><div class="board-scroll"><div class="board-content ${s.game}">${board()}</div></div><div class="table-status"><span>${selected?'Выберите место для карты':pair!==null?'Теперь выберите вторую карту':'Каждому ходу — своё время'}</span><span>${s.game==='freecell'?'Все карты открыты':s.game==='pyramid'?'Осталось '+s.columns.flat().length+' карт':s.game==='tripeaks'?'Осталось '+s.columns.flat().length+' карт':'Нажмите дважды, чтобы отправить карту в дом'}</span></div>${paused?`<div class="pause-overlay"><span>Ⅱ</span><h2>Минута для себя</h2><p>Партия подождёт. Время остановлено.</p><button class="gold-button" data-action="pause">${icon('play')}Продолжить</button></div>`:''}</section><div class="game-toolbar"><div><button data-action="undo" ${!se.history.length||s.won?'disabled':''}>${icon('undo')}Отменить <kbd>Ctrl Z</kbd></button><button data-action="hint">${icon('hint')}Подсказка <kbd>H</kbd></button>${page!=='tower-game'?`<button data-action="auto">${icon('check')}В дома</button>`:''}</div><div><button data-action="rules">${icon('help')}Правила</button><button data-action="new">${icon('restart')}Новая игра</button></div></div><div class="game-footnote"><button class="deal-id" data-action="copy-deal">№ ${s.seed} · скопировать</button> Перетаскивайте карты или выбирайте карту и место нажатием. <span>Space — колода · Esc — снять выбор</span></div>`;}
function modalHtml(){if(!modal)return '';const se=session();let body='';
  if(modal==='rules')body=`<div class="modal-glyph">${info[active].icon}</div><div class="eyebrow">КАК ИГРАТЬ</div><h2>${info[active].name}</h2><p>${info[active].rules}</p><p class="muted">Кликните карту, затем место назначения, или перетащите. Двойное нажатие отправляет карту в дом. Подсказка показывает допустимый ход, но не гарантирует решение.</p><button class="primary-button" data-action="close">Всё понятно</button>`;
  if(modal==='new')body=`<div class="modal-glyph">♧</div><h2>Новая история?</h2><p>Текущая партия будет заменена. Можно повторить эту раздачу с самого начала или открыть новую.</p>${active==='klondike'?`<label class="select-label">Карты из колоды<select id="draw-count"><option value="1" ${se?.state.drawCount===1?'selected':''}>По одной карте</option><option value="3" ${se?.state.drawCount===3?'selected':''}>По три карты</option></select></label>`:''}${active==='spider'?`<label class="select-label">Количество мастей<select id="suits">${[1,2,4].map(n=>`<option value="${n}" ${se?.state.suits===n?'selected':''}>${n} ${n===1?'масть · легко':n===2?'масти · средне':'масти · сложно'}</option>`).join('')}</select></label>`:''}<button class="primary-button" data-action="deal">Новая раздача</button><button class="soft-button" data-action="restart">Повторить раздачу</button>`;
  if(modal==='win')body=`<div class="victory-medal">${badge(7)}</div><div class="victory-sparks">${Array.from({length:18},(_,i)=>`<i style="--n:${i}"></i>`).join('')}</div><div class="win-stars">✦ ✧ ✦</div><div class="eyebrow">ПРЕКРАСНАЯ ПАРТИЯ</div><h2>Всё сложилось!</h2><p>Ещё одна маленькая победа — ваша.${se?.daily?'<br>Задание дня отмечено как пройденное.':''}</p><div class="win-stats"><div><b>${time(se?.seconds??0)}</b><small>ВРЕМЯ</small></div><div><b>${se?.state.moves}</b><small>ХОДЫ</small></div><div><b>${se?.state.score}</b><small>ОЧКИ</small></div></div><div class="win-xp">${lastXP?`+${lastXP} XP · Мастерство растёт`:'Эта раздача уже есть в вашей истории'}</div><button class="primary-button" data-action="deal">Ещё одну партию</button><button class="soft-button" data-nav="journey">Мои достижения и награды</button><button class="soft-button" data-nav="home">В коллекцию</button>`;
  if(modal==='stuck')body=`<div class="modal-glyph">✧</div><h2>Пока нет ходов</h2><p>В этой позиции нет допустимого хода или доступного резерва. Попробуйте отменить несколько ходов, повторить раздачу или начать новую.</p><button class="primary-button" data-action="close">Вернуться к столу</button><button class="soft-button" data-action="new">Выбрать новую раздачу</button>`;
  if(modal==='replace-daily')body=`<div class="modal-glyph">☀</div><h2>Открыть задание дня?</h2><p>Сохранённая обычная партия этой игры будет заменена ежедневной раздачей.</p><button class="primary-button" data-action="confirm-daily">Начать задание</button>`;
  if(modal==='race-replace')body=`<div class="modal-glyph">⚔</div><h2>Начать новую дуэль?</h2><p>Текущая дуэль завершится поражением: −12 рейтинга. Затем начнётся партия с новым соперником.</p><button class="primary-button" data-action="race-start-confirm">Завершить и начать</button>`;
  if(modal==='race-concede')body=`<div class="modal-glyph">✧</div><h2>Завершить дуэль?</h2><p>Поражение изменит рейтинг на −12. Можно просто вернуться позже: оба стола сохраняются.</p><button class="primary-button" data-action="race-concede-confirm">Признать поражение</button><button class="soft-button" data-action="close">Продолжить игру</button>`;
  if(modal==='race-result'){const r=club().race!,won=r.status==='win';body=`<div class="win-stars">${won?'✦ ✧ ✦':'✧'}</div><div class="eyebrow">ДУЭЛЬ ЗАВЕРШЕНА</div><h2>${won?'Ваша красивая победа!':'В этот раз — соперник'}</h2><p>${won?'Вы первыми собрали все четыре дома.':'У каждой партии есть продолжение. В следующей раздаче всё может сложиться иначе.'}</p><div class="win-stats"><div><b>${time(r.finishedAt??0)}</b><small>ВРЕМЯ</small></div><div><b>${won?'+24':'−12'}</b><small>РЕЙТИНГ</small></div><div><b>+${r.reward}</b><small>МОНЕТЫ</small></div></div><button class="primary-button" data-nav="duel">Выбрать соперника</button><button class="soft-button" data-nav="league">Моё место в лиге</button>`;}
  if(modal==='tower-win'){const t=towerRun()!;body=`<div class="win-stars">♛</div><div class="eyebrow">ЦАРЬ ГОРЫ · ЭТАЖ ${t.floor}</div><h2>${t.floor===7?'Вершина покорена!':'Ещё на ступень выше'}</h2><p>Испытание пройдено. Награда: ${50+t.floor*25} монет. ${t.floor===7?'Вы — царь этой башни.':'Впереди — более строгие условия и новая раздача.'}</p>${t.floor<7?'<button class="primary-button" data-action="tower-next">На следующий этаж ↑</button>':''}<button class="soft-button" data-nav="tower">Посмотреть башню</button>`;}
  if(modal==='tower-fail'||modal==='tower-retry')body=`<div class="modal-glyph">♜</div><h2>${modal==='tower-fail'?'Время этажа истекло':'Ещё одна попытка?'}</h2><p>Ваш подъём сохранён. Можно повторить ту же раздачу или бесплатно получить новую на этом этаже. Пройденные этажи останутся открыты.</p><button class="primary-button" data-action="restart">Повторить раздачу</button><button class="soft-button" data-action="tower-redeal">Новый вариант этажа</button><button class="soft-button" data-nav="tower">Вернуться к башне</button>`;
  if(modal==='marathon-win'){const m=journey(data).marathon!;body=`<div class="victory-medal">${badge(m.complete?8:3)}</div><h2>${m.complete?'Маршрут пройден!':'Ещё одна грань коллекции'}</h2><p>${m.complete?'Три разных пасьянса — три победы. Бонус маршрута: 180 монет и 250 XP.':'Этап завершён: +60 монет. Следующая игра откроет другую сторону вашего мастерства.'}</p><div class="win-xp">+${lastXP} XP за партию</div>${m.complete?'<button class="primary-button" data-nav="modes">Выбрать новое настроение</button>':'<button class="primary-button" data-action="marathon-next">Следующий этап →</button>'}<button class="soft-button" data-nav="journey">Мой путь</button>`;}
  if(modal==='marathon-retry')body=`<div class="modal-glyph">✧</div><h2>Изменить маршрут?</h2><p>Пройденные этапы останутся. Можно повторить текущую раздачу или бесплатно взять новый вариант этого этапа.</p><button class="primary-button" data-action="restart">Повторить раздачу</button><button class="soft-button" data-action="marathon-redeal">Новый вариант этапа</button>`;
  return `<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${modal==='rules'?'Правила игры':'Диалог игры'}"><button class="modal-close" data-action="close" aria-label="Закрыть">${icon('close')}</button>${body}</section></div>`;
}
let focusBeforeModal='';
let previousGameContext='';
function focusKey(el:Element|null){if(!(el instanceof HTMLElement))return '';for(const k of ['data-action','data-nav','data-card','data-game','data-quest','data-achievement'])if(el.hasAttribute(k))return `[${k}="${CSS.escape(el.getAttribute(k)!)}"]`;return '';}
let lastLeagueDate=moscowDate();
function openMarathon(){const m=journey(data).marathon!;if(!m.session)startMarathonStage(m);active=m.games[m.stage];page='marathon-game';modal=null;paused=false;selected=null;pair=null;highlighted=[];persist();render();}
function beginRace(){active='klondike';club().race=newRace(pendingBot,crypto.getRandomValues(new Uint32Array(1))[0]);page='race';paused=false;modal=null;selected=null;pair=null;persist();render();}
function enterTower(){let t=towerRun();if(!t||t.cleared.length===7){t=joinTower(towerGame);club().towers[towerGame]=t;}else if(t.session?.state.won&&t.floor<7)t.floor++;openTowerFloor(!t.session||t.session.state.won);}
function openTowerFloor(redeal=false){const t=towerRun()!;if(redeal||!t.session)startFloor(t,crypto.getRandomValues(new Uint32Array(1))[0]);active=t.game;page='tower-game';paused=false;modal=null;selected=null;pair=null;highlighted=[];persist();render();}
function render(){const context=['game','race','tower-game','marathon-game'].includes(page)?`${page}:${session()?.state.seed}`:'';const positions=new Map<string,DOMRect>();if(context&&context===previousGameContext&&data.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll<HTMLElement>('.game-table .card[data-id]').forEach(el=>positions.set(el.dataset.id!,el.getBoundingClientRect()));previousGameContext=context;const focus=focusKey(document.activeElement);const previouslyModal=!!document.querySelector('.modal');if(modal&&!previouslyModal)focusBeforeModal=focus;document.body.classList.toggle('no-motion',!data.settings.motion);document.body.classList.toggle('calm-game',session()?.variant==='calm'&&page==='game');document.body.classList.toggle('classic-faces',data.settings.faces==='classic');app.innerHTML=`${sidebar()}<main class="main ${['game','race','tower-game','marathon-game'].includes(page)?'playing':''}">${page==='race'&&club().race?raceView(club(),board(),paused,data.settings.theme,data.settings.back):page==='tower-game'||page==='game'||page==='marathon-game'?gameView():page==='modes'?header('Играть по-своему','Выберите темп, длину партии и новый вызов.')+modesView(data):page==='journey'?header('Путь коллекционера','Цели, открытия и знаки вашего мастерства.')+journeyView(data):page==='duel'?header('У каждой игры — свой соперник','Вызовите одного из шести ботов на честную гонку.')+duelLobby(club()):page==='league'?header('Лига маленьких побед','Знакомые имена. Новый порядок каждый день.')+leagueView(club()):page==='shop'?header('Магазин рубашек','Зарабатывайте монеты. Собирайте свою коллекцию.')+shopView(club(),data.settings.back):page==='tower'?header('Царь горы','Выберите свой путь. Покорите свою вершину.')+towerLobby(club(),towerGame):page==='daily'?daily():page==='stats'?stats():page==='settings'?settings():home()}</main>${modalHtml()}`;if(modal)document.querySelector<HTMLButtonElement>('.modal button')?.focus();else {document.querySelector<HTMLElement>(previouslyModal?focusBeforeModal||'body':focus||'body')?.focus({preventScroll:true});}if(positions.size)document.querySelectorAll<HTMLElement>('.game-table .card[data-id]').forEach(el=>{const old=positions.get(el.dataset.id!);if(!old)return;const next=el.getBoundingClientRect(),dx=old.left-next.left,dy=old.top-next.top;if(Math.abs(dx)+Math.abs(dy)>2)el.animate([{transform:`translate(${dx}px,${dy}px)`,zIndex:100},{transform:'translate(0,0)',zIndex:100}],{duration:210,easing:'cubic-bezier(.2,.8,.2,1)'});});}
function parsePlace(text:string):Place{const [zone,p,i]=text.split(':');return {zone:zone as Place['zone'],pile:Number(p),index:Number(i)};}
function choose(p:Place){const se=session();if(!se||paused||modal)return;const s=se.state,c=pile(s,p)[p.index];if(!c?.up)return;
  if(s.game==='pyramid'||s.game==='tripeaks'||s.game==='golf'){
    if(s.game==='golf'&&(p.zone!=='columns'||p.index!==s.columns[p.pile].length-1))return;
    if(p.zone==='columns'&&!exposed(s,p.pile))return;
    if(s.game==='tripeaks'||s.game==='golf'){if(!move({type:'pair',ids:[c.id]}))toast('Нужна свободная карта на единицу старше или младше.');return;}
    if(c.rank===13){move({type:'pair',ids:[c.id]});return;}
    if(pair===c.id)pair=null;else if(pair!==null){if(move({type:'pair',ids:[pair,c.id]}))return;pair=c.id;toast('Сумма пары должна быть равна 13.');}else pair=c.id;
    render();return;
  }
  if(selected){if(selected.zone===p.zone&&selected.pile===p.pile&&selected.index===p.index){selected=null;render();return;}if(move({type:'move',from:selected,to:{zone:p.zone,pile:p.pile}}))return;}
  selected=p;highlighted=[];render();
}
function autoHome(){const se=session();if(!se||paused||modal||page==='tower-game')return;let count=0;while(count<(page==='race'?1:104)){const a=hint(se.state);if(a?.type!=='move'||a.to.zone!=='foundations')break;if(!move(a))break;count++;}if(!count)toast('Нет карт, которые сейчас можно отправить в дома.');}
function doHint(){const se=session();if(!se||paused||modal)return;if(page==='tower-game'){const t=towerRun()!;if(t.failed||t.hintUsed>=towerRules(t.game,t.floor).hints){toast('На этом этаже больше нет подсказок.');return;}}const a=hint(se.state);if(!a){modal='stuck';render();return;}se.hintsUsed=(se.hintsUsed??0)+1;if(page==='tower-game')towerRun()!.hintUsed++;persist();highlighted=[];selected=null;pair=null;if(a.type==='move'){highlighted=pile(se.state,a.from).slice(a.from.index).map(c=>c.id);toast(`Перенесите ${ranks[pile(se.state,a.from)[a.from.index].rank]} ${symbols[pile(se.state,a.from)[a.from.index].suit]} ${a.to.zone==='foundations'?'в дом':a.to.zone==='cells'?'в свободную ячейку':`в столбец ${a.to.pile+1}`}.`);}else if(a.type==='pair'){highlighted=a.ids;toast(se.state.game==='pyramid'?'Уберите выделенные карты.':'Перенесите выделенную карту в сброс.');}else toast('Откройте следующую карту из колоды (Space).');render();if(a.type==='draw')document.querySelector('.stock')?.classList.add('hinted');}
app.addEventListener('click',e=>{
  const target=e.target as HTMLElement,button=target.closest<HTMLElement>('[data-filter],[data-quest],[data-achievement],[data-faces],[data-opponent],[data-buy],[data-tower-game],[data-action],[data-nav],[data-game],[data-daily],[data-card],[data-target],[data-theme],[data-back],[data-toggle]');if(!button)return;
  if(button.dataset.filter){collectionFilter=button.dataset.filter;render();return;}
  if(button.dataset.quest){if(claimQuest(data,button.dataset.quest,moscowDate())){persist();render();toast('Награда получена: монеты и опыт добавлены.');}return;}
  if(button.dataset.achievement){if(claimAchievement(data,button.dataset.achievement)){persist();render();toast('Знак мастерства в вашей коллекции. Награда получена!');}return;}
  if(button.dataset.faces){data.settings.faces=button.dataset.faces as 'ornate'|'classic';persist();render();return;}
  if(button.dataset.opponent){pendingBot=button.dataset.opponent;if(club().race?.status==='playing'){modal='race-replace';render();}else beginRace();return;}
  if(button.dataset.buy){const id=button.dataset.buy,result=purchase(club(),id);if(result==='poor'){toast('Пока не хватает монет. Их можно заработать в играх, дуэлях и башнях.');return;}if(result==='bought'||result==='owned'){data.settings.back=id;persist();render();toast(result==='bought'?'Рубашка куплена и выбрана!':'Рубашка выбрана.');}return;}
  if(button.dataset.towerGame){towerGame=button.dataset.towerGame as Game;render();return;}
  if(button.dataset.nav){page=button.dataset.nav;modal=null;selected=null;pair=null;paused=false;persist();render();return;}
  if(button.dataset.game){start(button.dataset.game as Game);return;}
  if(button.dataset.daily){active=button.dataset.daily as Game;if(session()&&!session()!.daily&&!session()!.state.won){modal='replace-daily';render();}else start(active,true);return;}
  if(button.dataset.theme){data.settings.theme=button.dataset.theme;persist();render();return;}
  if(button.dataset.back){data.settings.back=button.dataset.back;persist();render();return;}
  if(button.dataset.toggle){const key=button.dataset.toggle as 'sound'|'motion';data.settings[key]=!data.settings[key];persist();render();return;}
  if(button.dataset.card){choose(parsePlace(button.dataset.card));return;}
  if(button.dataset.target&&selected){const [zone,p]=button.dataset.target.split(':');if(!move({type:'move',from:selected,to:{zone:zone as Place['zone'],pile:Number(p)}}))toast('Сюда эту карту положить нельзя.');return;}
  switch(button.dataset.action){
    case 'tutorial-close':journey(data).tutorialDone=true;persist();render();break;
    case 'guided-start':start('klondike',false,true);{const se=session()!;se.state=raceDeal(se.state.seed);se.initial=clone(se.state);se.variant='guided';persist();render();}break;
    case 'calm-start':start('tripeaks',false,true);session()!.variant='calm';persist();render();break;
    case 'numbered-start':{const g=(document.querySelector('#numbered-game') as HTMLSelectElement).value as Game,text=(document.querySelector('#deal-number') as HTMLInputElement).value,n=Number(text);if(!/^\d+$/.test(text)||!Number.isInteger(n)||n<0||n>4294967295){toast('Введите целое число от 0 до 4 294 967 295.');break;}start(g,false,true,n);session()!.variant='numbered';persist();render();break;}
    case 'marathon-start':{const j=journey(data);if(!j.marathon||j.marathon.complete){j.marathon=createMarathon(crypto.getRandomValues(new Uint32Array(1))[0]);startMarathonStage(j.marathon);}else if(j.marathon.session?.state.won&&!j.marathon.complete){j.marathon.stage++;startMarathonStage(j.marathon);}openMarathon();break;}
    case 'marathon-next':{const m=journey(data).marathon!;if(m.stage<2){m.stage++;m.attempt=0;startMarathonStage(m);}openMarathon();break;}
    case 'marathon-redeal':{const m=journey(data).marathon!;if(m.cleared.includes(m.stage)){toast('Этап уже пройден. Перейдите к следующему.');break;}m.attempt=(m.attempt??0)+1;startMarathonStage(m);openMarathon();break;}
    case 'copy-deal':{const text=String(session()?.state.seed??0);void navigator.clipboard?.writeText(text).then(()=>toast('Номер раздачи скопирован.'),()=>toast('Номер раздачи: '+text));break;}
    case 'race-start-confirm':if(club().race?.status==='playing')finishRace(club(),'loss');beginRace();break;
    case 'race-resume':active='klondike';page='race';paused=false;modal=null;render();break;
    case 'race-giveup':if(club().race?.status==='playing'){modal='race-concede';render();}break;
    case 'race-concede-confirm':finishRace(club(),'loss');paused=false;modal='race-result';persist();render();break;
    case 'tower-enter':enterTower();break;
    case 'tower-next':{const t=towerRun()!;if(t.floor<7)t.floor++;openTowerFloor(true);break;}
    case 'tower-redeal':openTowerFloor(true);break;
    case 'close':modal=null;render();break;
    case 'draw':if(!move({type:'draw'})){toast(session()?.state.game==='spider'&&session()!.state.columns.some(p=>!p.length)?'Сначала заполните все пустые столбцы.':'Колода закончилась. Попробуйте подсказку или отмену.');}break;
    case 'undo':undo();break;
    case 'hint':doHint();break;
    case 'auto':autoHome();break;
    case 'rules':modal='rules';render();break;
    case 'new':modal=page==='marathon-game'?'marathon-retry':page==='tower-game'?'tower-retry':'new';render();break;
    case 'deal':start(active,false,true);break;
    case 'confirm-daily':start(active,true,true);break;
    case 'restart':{const se=session()!;se.state=clone(se.initial);se.history=[];se.seconds=0;se.hintsUsed=0;se.undosUsed=0;if(page==='tower-game'){const t=towerRun()!;t.failed=false;t.hintUsed=0;t.undoUsed=0;}selected=null;pair=null;paused=false;modal=null;persist();render();break;}
    case 'pause':paused=!paused;selected=null;persist();render();break;
    case 'export':{const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`Пасьянс-${moscowDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Резервная копия сохранена.');break;}
    case 'import':document.querySelector<HTMLInputElement>('#import-file')?.click();break;
  }
});
app.addEventListener('dblclick',e=>{const button=(e.target as HTMLElement).closest<HTMLElement>('[data-card]');if(!button||!session()||paused||modal)return;const from=parsePlace(button.dataset.card!),s=session()!.state;if(s.game!=='klondike'&&s.game!=='freecell'&&s.game!=='yukon')return;for(let i=0;i<4;i++)if(canMove(s,from,{zone:'foundations',pile:i})){move({type:'move',from,to:{zone:'foundations',pile:i}});break;}});
let dragged:Place|null=null;
app.addEventListener('dragstart',e=>{const el=(e.target as HTMLElement).closest<HTMLElement>('[data-card]');if(!el||paused||modal){e.preventDefault();return;}dragged=parsePlace(el.dataset.card!);e.dataTransfer?.setData('text/plain',el.dataset.card!);if(e.dataTransfer)e.dataTransfer.effectAllowed='move';});
app.addEventListener('dragover',e=>{if((e.target as HTMLElement).closest('[data-target]'))e.preventDefault();});
app.addEventListener('drop',e=>{e.preventDefault();const dest=(e.target as HTMLElement).closest<HTMLElement>('[data-target]');if(!dragged||!dest)return;const [zone,p]=dest.dataset.target!.split(':');const s=session()?.state;if(s?.game==='pyramid'||s?.game==='tripeaks'||s?.game==='golf')return;if(!move({type:'move',from:dragged,to:{zone:zone as Place['zone'],pile:Number(p)}}))toast('Этот ход недоступен.');dragged=null;});
app.addEventListener('dragend',()=>{dragged=null;});
app.addEventListener('change',async e=>{const input=e.target as HTMLInputElement;if(input.id!=='import-file'||!input.files?.[0])return;try{if(input.files[0].size>12_000_000)throw Error();const d:unknown=JSON.parse(await input.files[0].text());if(!validData(d))throw Error();if(!confirm('Заменить текущий прогресс данными из файла?'))return;data=normalizeData(d);active=data.last;persist();render();toast('Прогресс восстановлен.');}catch{toast('Файл повреждён или имеет неподдерживаемый формат.');}finally{input.value='';}});
document.addEventListener('keydown',e=>{
  if(!modal&&(e.key==='Enter'||e.code==='Space')&&(e.target as HTMLElement).matches('[data-target][tabindex]')){e.preventDefault();(e.target as HTMLElement).click();return;}
  if(modal){if(e.key==='Escape'){modal=null;render();}if(e.key==='Tab'){const focusable=[...document.querySelectorAll<HTMLElement>('.modal button,.modal select')];const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}
  if(!['game','race','tower-game','marathon-game'].includes(page)||(e.target as HTMLElement).matches('input,select,textarea'))return;
  if((e.ctrlKey||e.metaKey)&&e.code==='KeyZ'){e.preventDefault();undo();}
  else if(e.code==='KeyH'){e.preventDefault();doHint();}else if(e.code==='Space'&&!(e.target as HTMLElement).closest('button')){e.preventDefault();move({type:'draw'});}else if(e.key==='Escape'){selected=null;pair=null;highlighted=[];render();}
});
setInterval(()=>{const se=session();if(['game','race','tower-game','marathon-game'].includes(page)&&se&&!se.state.won&&!paused&&!modal&&!document.hidden&&!(page==='race'&&club().race?.status!=='playing')&&!(page==='tower-game'&&towerRun()?.failed)){se.seconds++;const timer=document.querySelector('#timer');if(timer)timer.textContent=time(se.seconds);if(page==='race'){const r=club().race!;if(se.seconds>=r.nextAt){botStep(r);if(r.bot.won){finishRace(club(),'loss');modal='race-result';persist();render();}else{const panel=document.querySelector('#bot-live');if(panel)panel.innerHTML=botPanel(r);persist();}}}if(page==='tower-game'){const t=towerRun()!,limit=towerRules(t.game,t.floor).seconds;if(limit&&se.seconds>=limit){t.failed=true;modal='tower-fail';persist();render();}}if(se.seconds%5===0)persist();}const date=moscowDate();if(date!==lastLeagueDate){lastLeagueDate=date;if(['league','daily','tower','journey'].includes(page))render();}},1000);
addEventListener('beforeunload',persist);document.addEventListener('visibilitychange',()=>{if(document.hidden)persist();});
